# General Awareness: Indian Polity and Indian Economy. Constitutional and institutional facts only, no office-holders.
ITEMS = [
    # ---------- Practice Test 1 ----------
    S(1, 1, "Constitution", "Fundamental Rights are contained in which Part of the Constitution of India?",
      ["Part III", "Part II", "Part IV", "Part IV-A"],
      "Part III (Articles 12 to 35) lists the Fundamental Rights. Part II deals with citizenship, Part IV with the Directive Principles and Part IV-A with Fundamental Duties."),
    S(1, 1, "Union and states", "Who is the Supreme Commander of the Indian Armed Forces?",
      ["The President", "The Prime Minister", "The Defence Minister", "The Chief of Defence Staff"],
      "Article 53 vests the supreme command of the defence forces in the President."),
    S(1, 1, "Union and states", "What is the minimum age to be elected President of India?",
      ["35 years", "25 years", "30 years", "40 years"],
      "Article 58 requires the President to be at least 35. A Lok Sabha member must be 25 and a Rajya Sabha member 30."),
    S(1, 2, "Constitution", "Article 21 of the Constitution protects which right?",
      ["Life and personal liberty", "Equality before law", "Freedom of religion", "Constitutional remedies"],
      "Article 21 says no person shall be deprived of life or personal liberty except according to procedure established by law. Equality before law is Article 14 and constitutional remedies Article 32."),
    S(1, 2, "Constitution", "Who was elected the permanent President of the Constituent Assembly?",
      ["Dr Rajendra Prasad", "Dr B. R. Ambedkar", "Jawaharlal Nehru", "Sardar Vallabhbhai Patel"],
      "Dr Rajendra Prasad was elected President of the Constituent Assembly in December 1946; Dr Sachchidananda Sinha had been its temporary chairman. Dr Ambedkar chaired the Drafting Committee."),
    S(1, 2, "Union and states", "Who administers the oath of office to the Governor of a state?",
      ["The Chief Justice of that state's High Court", "The President of India", "The Chief Minister of that state", "The Speaker of the state Assembly"],
      "Under Article 159 the Governor takes the oath before the Chief Justice of the High Court of the state, or in his absence the senior-most judge available."),
    S(1, 2, "Banking", "In which year were 14 major commercial banks in India nationalised?",
      ["1969", "1980", "1955", "1991"],
      "14 major banks were nationalised in July 1969 and six more in 1980. 1955 was the year the Imperial Bank became the State Bank of India."),
    S(1, 2, "Taxation", "Which constitutional body recommends how the net proceeds of taxes are shared between the Union and the states?",
      ["Finance Commission", "NITI Aayog", "GST Council", "Reserve Bank of India"],
      "The Finance Commission, set up every five years under Article 280, recommends the division of taxes between the Union and the states and among the states."),
    S(1, 1, "Banking", "Which of these is a function of the Reserve Bank of India?",
      ["Acting as banker to the government", "Collecting income tax from people", "Preparing the Union Budget", "Conducting national elections"],
      "The RBI is banker to the Union and state governments, issues currency and regulates banks. Income tax is collected by the Income Tax Department and the budget is prepared by the Ministry of Finance."),
    S(1, 2, "Banking", "The repo rate is the rate at which:",
      ["the RBI lends short-term funds to commercial banks", "commercial banks lend money to their best customers", "the RBI borrows money from the public through bonds", "commercial banks keep cash reserves with the RBI"],
      "Repo is the rate at which the RBI lends to banks against government securities. The reserve banks must keep with the RBI is the cash reserve ratio, which is a ratio, not a lending rate."),

    # ---------- Practice Test 2 ----------
    S(2, 1, "Constitution", "The Directive Principles of State Policy are contained in which Part of the Constitution?",
      ["Part IV", "Part III", "Part V", "Part IX"],
      "Part IV (Articles 36 to 51) contains the Directive Principles. They are not enforceable in court but guide the government in making laws."),
    S(2, 2, "Constitution", "Which Article of the Constitution abolishes titles, except military and academic distinctions?",
      ["Article 18", "Article 15", "Article 19", "Article 14"],
      "Article 18 bars the State from conferring titles other than military or academic distinctions. Article 14 is equality before law, 15 bars discrimination and 19 protects freedoms such as speech."),
    S(2, 2, "Union and states", "The President of India is elected by an electoral college made up of:",
      ["Elected members of Parliament and of the state Legislative Assemblies", "All members of the Lok Sabha and the Rajya Sabha, elected and nominated", "Elected members of the Lok Sabha and of all Legislative Councils", "Members of the Union Council of Ministers and all state Governors"],
      "Under Article 54 the electoral college has the elected members of both Houses of Parliament and the elected members of the Legislative Assemblies of the states (including Delhi and Puducherry). Nominated members and Legislative Council members do not vote."),
    S(2, 2, "Constitution", "The Right to Property was removed from the list of Fundamental Rights by which amendment?",
      ["44th Amendment, 1978", "42nd Amendment, 1976", "24th Amendment, 1971", "52nd Amendment, 1985"],
      "The 44th Amendment, 1978 removed property from Part III and made it a legal right under Article 300A."),
    S(2, 2, "Parliament", "A Money Bill can be introduced only in:",
      ["the Lok Sabha", "the Rajya Sabha", "either House of Parliament", "a joint sitting of Parliament"],
      "Under Article 109 a Money Bill cannot be introduced in the Rajya Sabha, so it starts in the Lok Sabha, and Article 117 requires the President's recommendation. The Rajya Sabha can only recommend changes within 14 days."),
    S(2, 1, "Union and states", "Who is the constitutional head of a state government?",
      ["The Governor", "The Chief Minister", "The Chief Justice of the High Court", "The Speaker of the Legislative Assembly"],
      "The Governor is the constitutional head of a state, and executive power is exercised in the Governor's name. The Chief Minister heads the state Council of Ministers."),
    S(2, 2, "Elections", "Which Constitutional Amendment lowered the voting age from 21 to 18 years?",
      ["61st Amendment", "52nd Amendment", "73rd Amendment", "86th Amendment"],
      "The 61st Amendment Act, 1988 (in force from 1989) lowered the voting age to 18. The 52nd dealt with anti-defection and the 86th made education a Fundamental Right."),
    S(2, 1, "Taxation", "Which of these is a direct tax?",
      ["Income tax", "Goods and Services Tax", "Customs duty", "Excise duty"],
      "A direct tax is paid by the person on whom it is levied, such as income tax. GST, customs and excise are indirect taxes passed on to the buyer."),
    S(2, 2, "Banking", "NABARD is the apex institution for financing which sector?",
      ["Agriculture and rural development", "Small industries in cities", "Housing and real estate", "Exports and imports"],
      "The National Bank for Agriculture and Rural Development was set up in 1982. SIDBI serves small industries, NHB housing and EXIM Bank foreign trade."),
    S(2, 3, "Planning", "In the Constitution, the Union Budget is referred to as the:",
      ["Annual Financial Statement", "Consolidated Fund Statement", "Appropriation Account", "Economic Survey"],
      "Article 112 calls the budget the Annual Financial Statement. The Economic Survey is a separate report released before the budget."),

    # ---------- Drill only ----------
    S(0, 2, "Constitution", "Which writ orders a public official to perform a duty that the official has failed to perform?",
      ["Mandamus", "Certiorari", "Prohibition", "Quo warranto"],
      "Mandamus means \"we command\". Certiorari quashes a lower court's order, prohibition stops a lower court from going beyond its powers, and quo warranto asks by what authority a person holds an office."),
    S(0, 2, "Union and states", "The Election Commission of India is provided for under which Article?",
      ["Article 324", "Article 280", "Article 315", "Article 148"],
      "Article 324 vests the superintendence of elections in the Election Commission. Article 280 is the Finance Commission, 315 the Public Service Commissions and 148 the Comptroller and Auditor General."),
    S(0, 1, "Union and states", "Who is the head of the Union Council of Ministers?",
      ["The Prime Minister", "The President", "The Vice-President", "The Cabinet Secretary"],
      "Article 74 provides a Council of Ministers with the Prime Minister at its head to aid and advise the President."),
    S(0, 2, "Banking", "Which institution issues currency notes in India, except the one-rupee note?",
      ["Reserve Bank of India", "Ministry of Finance", "State Bank of India", "Security Printing and Minting Corporation"],
      "The RBI issues all currency notes except the one-rupee note, which is issued by the Government of India through the Ministry of Finance."),
]
